    def __init__(self):
        self.root = {}
    """
    Trie (Prefix Tree) supporting insert(word), search(word), and starts_with(prefix).

    >>> t = Trie(); t.insert('apple'); t.search('apple')
    True

    Hint:
        Use nested dictionaries where each node is a dict and '#' or '$' marks the end of a word.
